previewCss:
.darma-loader-darma-b17-sierpinski-build { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #f0abfc); width: var(--loader-size, 122px); height: calc(var(--loader-size, 122px) * .88); position: relative; }
.darma-loader-darma-b17-sierpinski-build span { position: absolute; background: linear-gradient(var(--accent-2), var(--accent)); clip-path: polygon(50% 0, 100% 100%, 0 100%); transform: scale(0); animation: darma-loader-darma-b17-sierpinski-build-sierp-grow calc(var(--loader-speed, 1s) * 3.4) cubic-bezier(.3, 1.4, .5, 1) infinite; }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(1) { left: 25%; top: 0; width: 50%; height: 50%; }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(2) { left: 0; top: 50%; width: 50%; height: 50%; animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(3) { left: 50%; top: 50%; width: 50%; height: 50%; animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(4) { left: 37.5%; top: 0; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(5) { left: 25%; top: 25%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(6) { left: 50%; top: 25%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(7) { left: 12.5%; top: 50%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed, 1s) * .68); }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(8) { left: 62.5%; top: 50%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed, 1s) * .68); }
.darma-loader-darma-b17-sierpinski-build span:nth-of-type(9) { left: 37.5%; top: 75%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed, 1s) * .92); }
@keyframes darma-loader-darma-b17-sierpinski-build-sierp-grow { 0%, 4% { transform: scale(0); opacity: 0; } 20%, 72% { transform: scale(1); opacity: 1; } 90%, 100% { transform: scale(0); opacity: 0; } }

